item.aggregated_output:
            self._remove_expired_locked()
            created = key not in self.entries
            expiry = None if ttl is None else time.time() + ttl
            self.entries[key] = {"value": value, "expires_at": expiry}
            self._persist_locked()
            return created

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            entry = self.entries.get(key)
            if entry is None:
                return False, None
            if not self._live(entry, time.time()):
                del self.entries[key]
                self._persist_locked()
                return False, None
            return True, entry["value"]

    def delete(self, key: str) -> bool:
        with self.lock:
            changed = self._remove_expired_locked()
            present = key in self.entries
            if present:
                del self.entries[key]
            if changed or present:
                self._persist_locked()
            return present

    def keys(self) -> list[str]:
        with self.lock:
            if self._remove_expired_locked():
                self._persist_locked()
            return sorted(self.entries)


class Server(ThreadingHTTPServer):
    daemon_threads = False
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], store: Store):
        self.store = store
        super().__init__(address, Handler)


class Handler(BaseHTTPRequestHandler):
    server: Server
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt: str, *args: Any) -> None:
        sys.stderr.write("%s - - [%s] %s\n" % (self.address_string(), self.log_date_time_string(), fmt % args))

    def _send_json(self, status: int, payload: Any, *, extra_headers: dict[str, str] | None = None) -> None:
        body = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        if extra_headers:
            for name, value in extra_headers.items():
                self.send_header(name, value)
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _error(self, status: int, message: str, *, headers: dict[str, str] | None = None) -> None:
        self._send_json(status, {"error": message}, extra_headers=headers)

    def _path(self) -> str:
        parsed = urlsplit(self.path)
        if parsed.query or parsed.fragment:
            raise RequestError(404, "unknown route")
        return parsed.path

    def _key(self, path: str) -> str:
        if not path.startswith(KEY_PREFIX):
            raise RequestError(404, "unknown route")
        encoded = path[len(KEY_PREFIX):]
        if not encoded or "/" in encoded or BAD_ESCAPE.search(encoded):
            raise RequestError(400, "invalid key")
        try:
            key = unquote_to_bytes(encoded).decode("utf-8")
        except UnicodeDecodeError as exc:
            raise RequestError(400, "invalid key") from exc
        if not key or "/" in key:
            raise RequestError(400, "invalid key")
        return key

    def _read_object(self) -> dict[str, Any]:
        transfer_encoding = self.headers.get("Transfer-Encoding")
        if transfer_encoding:
            raise RequestError(400, "transfer encoding is not supported")
        raw_length = self.headers.get("Content-Length")
        if raw_length is None:
            raise RequestError(411, "Content-Length is required")
        try:
            length = int(raw_length)
        except ValueError as exc:
            raise RequestError(400, "invalid Content-Length") from exc
        if length < 0:
            raise RequestError(400, "invalid Content-Length")
        if length > MAX_BODY:
            self.close_connection = True
            raise RequestError(413, "request body exceeds 1 MiB")
        raw = self.rfile.read(length)
        try:
            value = json.loads(raw.decode("utf-8"), parse_constant=Store._reject_constant)
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
            raise RequestError(400, "malformed JSON") from exc
        if not isinstance(value, dict):
            raise RequestError(400, "request body must be a JSON object")
        return value

    def do_GET(self) -> None:
        try:
            path = self._path()
            if path == "/health":
                self._send_json(200, {"status": "ok"})
            elif path == "/v1/keys":
                self._send_json(200, {"keys": self.server.store.keys()})
            else:
                key = self._key(path)
                found, value = self.server.store.get(key)
                if not found:
                    self._error(404, "key not found")
                else:
                    self._send_json(200, {"key": key, "value": value})
        except RequestError as exc:
            self._error(exc.status, exc.message)
        except (OSError, ValueError) as exc:
            self.log_error("request failed: %s", exc)
            self._error(500, "internal server error")

    def do_PUT(self) -> None:
        try:
            key = self._key(self._path())
            body = self._read_object()
            if "value" not in body or not set(body).issubset({"value", "ttl_seconds"}):
                raise RequestError(400, "body must contain value and optional ttl_seconds")
            ttl = body.get("ttl_seconds")
            if ttl is not None and (
                isinstance(ttl, bool)
                or not isinstance(ttl, (int, float))
                or not math.isfinite(ttl)
                or ttl <= 0
            ):
                raise RequestError(400, "ttl_seconds must be a finite number greater than zero")
            created = self.server.store.put(key, body["value"], ttl)
            self._send_json(201 if created else 200, {"key": key, "value": body["value"]})
        except RequestError as exc:
            self._error(exc.status, exc.message)
        except (OSError, ValueError) as exc:
            self.log_error("request failed: %s", exc)
            self._error(500, "internal server error")

    def do_DELETE(self) -> None:
        try:
            key = self._key(self._path())
            if not self.server.store.delete(key):
                self._error(404, "key not found")
                return
            self.send_response(204)
            self.send_header("Content-Type", "application/json")
        key = "hello world"
        path = "/v1/kv/" + quote(key)
        self.assertEqual(self.request("PUT", path, {"value": {"n": 1}})[0], 201)
        self.assertEqual(self.request("PUT", "/v1/kv/z", {"value": None})[0], 201)
        self.assertEqual(self.request("PUT", path, {"value": [1, 2]})[0], 200)
        self.assertEqual(self.request("GET", path)[2], {"key": key, "value": [1, 2]})
        self.assertEqual(self.request("GET", "/v1/keys")[2], {"keys": [key, "z"]})
        self.assertEqual(self.request("DELETE", path)[0], 204)
        self.assertEqual(self.request("GET", path)[0], 404)

    def test_ttl_validation_limits_and_routes(self):
        for ttl in (0, -1, True, float("inf")):
            self.assertEqual(self.request("PUT", "/v1/kv/x", {"value": 1, "ttl_seconds": ttl})[0], 400)
        self.assertEqual(self.request("PUT", "/v1/kv/x", {"value": 1, "ttl_seconds": 0.08})[0], 201)
        time.sleep(0.12)
        self.assertEqual(self.request("GET", "/v1/kv/x")[0], 404)
        self.assertEqual(self.request("GET", "/health")[2], {"status": "ok"})
        self.assertEqual(self.request("POST", "/health", {})[0], 405)
        self.assertEqual(self.request("GET", "/missing")[0], 404)
        self.assertEqual(self.request("PUT", "/v1/kv/a%2Fb", {"value": 1})[0], 400)
        huge = b"x" * (1024 * 1024 + 1)
        connection = http.client.HTTPConnection("127.0.0.1", self.port, timeout=3)
        connection.request("PUT", "/v1/kv/x", huge)
        self.assertEqual(connection.getresponse().status, 413)
        connection.close()

    def test_restart_persistence_and_expiry(self):
        self.assertEqual(self.request("PUT", "/v1/kv/keep", {"value": "yes"})[0], 201)
        self.assertEqual(self.request("PUT", "/v1/kv/drop", {"value": "no", "ttl_seconds": 0.08})[0], 201)
        self.stop()
        time.sleep(0.12)
        self.start()
        self.assertEqual(self.request("GET", "/v1/kv/keep")[2]["value"], "yes")
        self.assertEqual(self.request("GET", "/v1/kv/drop")[0], 404)
        persisted = json.loads(self.data.read_text())
        self.assertNotIn("drop", persisted["entries"])


